import{_ as e,o as i,c as r,ai as t}from"./chunks/framework.ampVZV4B.js";const A=JSON.parse('{"title":"AI 应用","description":"","frontmatter":{},"headers":[],"relativePath":"ai/app/index.md","filePath":"ai/app/index.md"}'),n={name:"ai/app/index.md"};function l(o,a,h,s,d,p){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="ai-应用" tabindex="-1">AI 应用 <a class="header-anchor" href="#ai-应用" aria-label="Permalink to “AI 应用”">​</a></h1><p>我关注的不是「AI 有哪些工具」，而是 <strong>AI 如何真正进入软件系统和业务流程</strong>。</p><p>工具与原理在 <a href="/my-vitepress-site/ai/dev/">AI 技术</a>；这里只讲切哪里、先做什么、怎么做成可用闭环。</p><hr><h2 id="三个分类" tabindex="-1">三个分类 <a class="header-anchor" href="#三个分类" aria-label="Permalink to “三个分类”">​</a></h2><h3 id="ai-应用-1" tabindex="-1">AI 应用 <a class="header-anchor" href="#ai-应用-1" aria-label="Permalink to “AI 应用”">​</a></h3><p>AI 接到真实业务场景：企业流程、MES / 工业现场、内容生产等。主题可以很多，<strong>不拆成长期子菜单</strong>。</p><h3 id="agent-应用" tabindex="-1">Agent 应用 <a class="header-anchor" href="#agent-应用" aria-label="Permalink to “Agent 应用”">​</a></h3><p>如何用 Agent（Tools / Skills / Context）解决真实问题、构建可执行应用。与 <a href="/my-vitepress-site/ai/dev/agent/agent-overview.html">技术 → Agent</a> 区分：那边讲 Agent 本身，这边讲落地用法。</p><blockquote><p>暂无足够真实的 Agent 应用文章，分类先留空，有内容再挂上。</p></blockquote><h3 id="ai-产品" tabindex="-1">AI 产品 <a class="header-anchor" href="#ai-产品" aria-label="Permalink to “AI 产品”">​</a></h3><p>从功能想法走到可验证的产品最小闭环：谁用、什么任务、成功标准、怎么评测。</p><hr><h2 id="我的判断" tabindex="-1">我的判断 <a class="header-anchor" href="#我的判断" aria-label="Permalink to “我的判断”">​</a></h2><ul><li>AI 应该进具体业务流程，不要孤立成一个聊天窗口。</li><li>不是处处都该上 AI。频繁、规则清楚、信息量大的环节更值得先试。</li><li>核心不只是模型，而是模型 + 上下文 + 工具 + 业务规则 + 人工验证。</li><li>高风险环节先做辅助，不要直接自动拍板。</li><li>一个功能有没有价值，最终看真实任务和结果，不看 Demo 漂不漂亮。</li></ul><hr><h2 id="关于这些内容" tabindex="-1">关于这些内容 <a class="header-anchor" href="#关于这些内容" aria-label="Permalink to “关于这些内容”">​</a></h2><p>这里记的是：我对 AI 如何进入真实业务和软件系统的思考、设计与实践探索。</p><p>我会尽量分开写：已经实际验证过的、基于项目形成的设计、还没验证的想法。不把概念方案写成已经落地的项目。</p>',19)])])}const _=e(n,[["render",l]]);export{A as __pageData,_ as default};
